import math

state = {
    't_last': 0,
    'look_timer': 0,
    'current_mirror': 'left_mirror',
}

def control(obs):
    dt = obs.get('dt', 0.1)

    state['look_timer'] += dt
    if state['look_timer'] > 1.2:
        state['look_timer'] = 0
        if state['current_mirror'] == 'left_mirror':
            state['current_mirror'] = 'right_mirror'
        else:
            state['current_mirror'] = 'left_mirror'

    target_look = 64.0 if state['current_mirror'] == 'left_mirror' else -64.0

    views = obs.get('views', {})
    rig = obs.get('rig', {})
    trailer_rear = rig.get('trailer_rear', [-6.3, 0.0])
    hitch_deg = obs.get('hitch_deg', 0.0)
    progress = obs.get('progress', {}).get('covered', 0.0)

    left_dist = 999.0
    right_dist = 999.0

    for vname, vdata in views.items():
        origin = vdata.get('origin', [0, 0])
        walls = vdata.get('walls', [])
        for bearing_deg, dist in walls:
            rad = math.radians(bearing_deg)
            px = origin[0] + dist * math.cos(rad)
            py = origin[1] + dist * math.sin(rad)

            if abs(px - trailer_rear[0]) < 2.5:
                if py > 0 and py < left_dist:
                    left_dist = py
                elif py < 0 and abs(py) < right_dist:
                    right_dist = abs(py)

    target_hitch = 0.0
    if left_dist < 900 and right_dist < 900:
        corridor_center_y = (left_dist - right_dist) / 2.0
        target_hitch = max(-15.0, min(15.0, corridor_center_y * 12.0))
    elif left_dist < 900:
        target_hitch = max(-15.0, min(15.0, (left_dist - 1.8) * 10.0))
    elif right_dist < 900:
        target_hitch = max(-15.0, min(15.0, (1.8 - right_dist) * 10.0))
    else:
        if progress < 18.0:
            target_hitch = 3.5
        else:
            target_hitch = 0.0

    hitch_err = hitch_deg - target_hitch
    steer_deg = hitch_err * 2.8
    steer_deg = max(-35.0, min(35.0, steer_deg))
    speed_mps = -0.75

    return {
        'steer_deg': steer_deg,
        'speed_mps': speed_mps,
        'look_deg': target_look
    }

