state = 'unpin'
unpin_timer = 0.0

def control(obs):
    global state, unpin_timer
    dt = obs.get('dt', 0.1)
    motion = obs.get('motion', {})
    hold = motion.get('hold_s', 0.0)
    hitch = obs.get('hitch_deg', 0.0)
    steer = obs.get('steer_deg', 0.0)
    progress = obs.get('progress', {})
    rem = progress.get('remaining', 56.5)

    look_target = -41.0

    if hold > 0.0:
        return {'steer_deg': 0.0, 'speed_mps': 0.0, 'look_deg': look_target}

    if state == 'unpin':
        unpin_timer += dt
        if unpin_timer < 2.5:
            return {'steer_deg': -15.0, 'speed_mps': 1.0, 'look_deg': look_target}
        else:
            state = 'reverse'
            unpin_timer = 0.0

    speed_mps = -0.9
    if rem < 10.0:
        speed_mps = -0.6
    if rem < 4.0:
        speed_mps = -0.35

    cam = obs.get('views', {}).get('camera')
    left_dists = []
    right_dists = []

    if cam and 'walls' in cam:
        import math
        for b, d in cam['walls']:
            rad_b = math.radians(b)
            vx = d * math.cos(rad_b)
            vy = d * math.sin(rad_b)

            rad_h = math.radians(hitch)
            tx = vx * math.cos(rad_h) - vy * math.sin(rad_h)
            ty = vx * math.sin(rad_h) + vy * math.cos(rad_h)

            if tx < 0:
                if ty > 0:
                    left_dists.append(ty)
                else:
                    right_dists.append(-ty)

    target_hitch = 0.0
    if left_dists and right_dists:
        min_l = min(left_dists)
        min_r = min(right_dists)
        lat_error = min_l - min_r
        target_hitch = max(-18.0, min(18.0, lat_error * 5.0))
    elif left_dists:
        min_l = min(left_dists)
        target_hitch = -8.0 if min_l < 2.2 else 0.0
    elif right_dists:
        min_r = min(right_dists)
        target_hitch = 8.0 if min_r < 2.2 else 0.0

    if rem < 6.0:
        target_hitch = 0.0

    hitch_error = hitch - target_hitch
    steer_target = hitch_error * 2.2
    steer_target = max(-35.0, min(35.0, steer_target))

    return {
        'steer_deg': steer_target,
        'speed_mps': speed_mps,
        'look_deg': look_target
    }

